#include <algorithm>
#include <cstddef>
#include <cstdint>
#include <limits>
namespace { constexpr int N=12,K=4; void put64(std::uint8_t*o,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(int i=0;i<8;i++)o[i]=static_cast<std::uint8_t>(b>>(8*i));} std::int64_t objective(const std::int64_t*d,int n,const int*c,int k){std::int64_t total=0;for(int i=0;i<n;i++){auto best=std::numeric_limits<std::int64_t>::max();for(int j=0;j<k;j++)best=std::min(best,d[i*N+c[j]]);total+=best;}return total;} }
extern "C" std::int64_t k_median_p1_local_search(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<2||len>150)return -1;auto n0=in[0],k0=in[1];if(n0<2||n0>N||k0<1||k0>K||k0>n0||len!=2+static_cast<std::size_t>(n0*n0+k0))return -1;int n=static_cast<int>(n0),k=static_cast<int>(k0);std::int64_t d[N][N]{};std::size_t p=2;for(int i=0;i<n;i++)for(int j=0;j<n;j++){auto x=in[p++];if(x<0||x>1000)return -1;d[i][j]=x;}for(int i=0;i<n;i++)for(int j=0;j<n;j++){if(d[i][j]!=(i==j?0:d[i][j])||d[i][j]!=d[j][i]||(i!=j&&d[i][j]==0))return -1;for(int h=0;h<n;h++)if(d[i][j]>d[i][h]+d[h][j])return -1;}bool selected[N]{};int c[K];for(int i=0;i<k;i++){auto x=in[p++];if(x<0||x>=n||selected[x])return -1;c[i]=static_cast<int>(x);selected[x]=true;}std::sort(c,c+k);auto current=objective(&d[0][0],n,c,k);for(;;){auto best=current;int bestc[K];std::copy(c,c+k,bestc);bool have=false;for(int leave=0;leave<k;leave++)for(int enter=0;enter<n;enter++)if(!selected[enter]){int cand[K];std::copy(c,c+k,cand);cand[leave]=enter;std::sort(cand,cand+k);auto value=objective(&d[0][0],n,cand,k);if(value<current&&(value<best||(value==best&&(!have||std::lexicographical_compare(cand,cand+k,bestc,bestc+k))))){best=value;std::copy(cand,cand+k,bestc);have=true;}}if(!have)break;for(int i=0;i<k;i++)selected[c[i]]=false;std::copy(bestc,bestc+k,c);for(int i=0;i<k;i++)selected[c[i]]=true;current=best;}auto bytes=8*static_cast<std::size_t>(2+k);if(!out||cap<bytes)return -2;put64(out,current);put64(out+8,k);for(int i=0;i<k;i++)put64(out+16+8*i,c[i]);return static_cast<std::int64_t>(bytes);}
